/**
 * CSC ENTITY ROUND 3 — Model A (v2)
 * Page 15 only.
 * - Collapse Rank Math Person node(s) to a single Person
 * - @id MUST remain: https://adanabosanmaavukati.org/avukat-ceren-sumer-cilli/#person
 * - Preserve audited fields from the two pre-fix Rank Math Person variants
 *   (sameAs union, image, worksFor, address, mainEntityOfPage)
 * Custom content JSON-LD (#ceren-sumer-cilli) is NOT modified by this filter.
 * Other pages / Article.author / Round 2 author identity are untouched.
 */

if (!defined('ABSPATH')) {
	return;
}

function csc_r3_is_ceren_profile_page() {
	return is_page(15) || is_page('avukat-ceren-sumer-cilli');
}

add_filter('astra_the_title_enabled', function ($enabled) {
	if (csc_r3_is_ceren_profile_page()) {
		return false;
	}
	return $enabled;
});

function csc_r3_unique_same_as($urls) {
	$out = array();
	foreach ((array) $urls as $url) {
		$url = html_entity_decode(trim((string) $url), ENT_QUOTES | ENT_HTML5, 'UTF-8');
		if ($url !== '' && !in_array($url, $out, true)) {
			$out[] = $url;
		}
	}
	return $out;
}

function csc_r3_merge_person_nodes(array $a, array $b) {
	$out = $a;
	foreach ($b as $key => $val) {
		if ($key === '@context') {
			continue;
		}
		if ($key === 'sameAs') {
			$out['sameAs'] = csc_r3_unique_same_as(array_merge(
				isset($out['sameAs']) ? (array) $out['sameAs'] : array(),
				is_array($val) ? $val : array($val)
			));
			continue;
		}
		if (!array_key_exists($key, $out) || $out[$key] === null || $out[$key] === '') {
			$out[$key] = $val;
			continue;
		}
		if (wp_json_encode($out[$key]) === wp_json_encode($val)) {
			continue;
		}
		if ($key === 'description' && is_string($out[$key]) && is_string($val) && mb_strlen($val) > mb_strlen($out[$key])) {
			$out[$key] = $val;
		}
	}
	return $out;
}

/**
 * Audited field union from the two Rank Math Person nodes that previously
 * shared #person (ENTITY ROUND 3 backup 2026-08-27). Used only to fill gaps
 * after Rank Math emits a single incomplete Person (#schema-*).
 */
