add_filter('rank_math/json_ld', function ($data, $jsonld) {
	if (!is_array($data) || !csc_r3_is_ceren_profile_page()) {
		return $data;
	}

	$target_id = 'https://adanabosanmaavukati.org/avukat-ceren-sumer-cilli/#person';
	$profile_url = 'https://adanabosanmaavukati.org/avukat-ceren-sumer-cilli/';

	$person_keys = array();
	$persons = array();
	foreach ($data as $key => $node) {
		if (!is_array($node)) {
			continue;
		}
		$types = isset($node['@type']) ? (array) $node['@type'] : array();
		if (in_array('Person', $types, true)) {
			$person_keys[] = $key;
			$persons[] = $node;
		}
	}

	if (!$persons && isset($data['@graph']) && is_array($data['@graph'])) {
		$rest = array();
		$g_persons = array();
		foreach ($data['@graph'] as $node) {
			$types = is_array($node) && isset($node['@type']) ? (array) $node['@type'] : array();
			if (in_array('Person', $types, true)) {
				$g_persons[] = $node;
			} else {
				$rest[] = $node;
			}
		}
		if ($g_persons) {
			$merged = array_shift($g_persons);
			foreach ($g_persons as $p) {
				$merged = csc_r3_merge_person_nodes($merged, $p);
			}
			$merged = csc_r3_merge_person_nodes($merged, csc_r3_audited_person_field_union());
			$merged['@type'] = 'Person';
			$merged['@id'] = $target_id;
			$merged['url'] = $profile_url;
			if (isset($merged['name']) && strpos((string) $merged['name'], '|') !== false) {
				$merged['name'] = 'Ceren Sümer Cilli';
			}
			$data['@graph'] = array_merge($rest, array($merged));
		}
		return $data;
	}

	if (!$persons) {
		return $data;
	}

	$merged = array_shift($persons);
	foreach ($persons as $p) {
		$merged = csc_r3_merge_person_nodes($merged, $p);
	}
	// Fill gaps from audited union of the previous duplicate pair (Model A).
	$merged = csc_r3_merge_person_nodes($merged, csc_r3_audited_person_field_union());
	$merged['@type'] = 'Person';
	$merged['@id'] = $target_id;
	$merged['url'] = $profile_url;
	if (isset($merged['name']) && strpos((string) $merged['name'], '|') !== false) {
		$merged['name'] = 'Ceren Sümer Cilli';
	}
	if (empty($merged['jobTitle'])) {
		$merged['jobTitle'] = 'Avukat';
	}
	$merged['sameAs'] = csc_r3_unique_same_as(isset($merged['sameAs']) ? $merged['sameAs'] : array());

	foreach ($person_keys as $key) {
		unset($data[$key]);
	}
	$data['Person'] = $merged;
	return $data;
}, 999, 2);
